const languageSelect = document.getElementById('language');
const languageTags = { zh: 'zh-CN', en: 'en', ja: 'ja' };
const storageKey = 'linsama-language';
function setLanguage(language) {
  const strings = messages[language];
  document.documentElement.lang = languageTags[language];
  document.title = strings.title;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    // Markup comes only from the bundled, author-maintained translations.
    element.innerHTML = strings[element.dataset.i18n];
  });
  document.querySelectorAll('[data-i18n-attr]').forEach(element => {
    element.setAttribute(element.dataset.i18nAttr, strings[element.dataset.i18nKey]);
  });
  languageSelect.value = language;
}
let savedLanguage;
try { savedLanguage = localStorage.getItem(storageKey); } catch {}
const browserLanguage = (navigator.languages || [navigator.language])
  .map(language => language.toLowerCase().split('-')[0])
  .find(language => Object.hasOwn(messages, language));
setLanguage(Object.hasOwn(messages, savedLanguage) ? savedLanguage : browserLanguage || 'en');
languageSelect.hidden = false;
languageSelect.addEventListener('change', () => {
  const language = languageSelect.value;
  setLanguage(language);
  try { localStorage.setItem(storageKey, language); } catch {}
});
